        [Fact]
        public async Task CreateOrderAsync_OneInvalidQuantityAmongValidItems_RejectsWholeRequestAndPersistsNothing()
        {
            var db = CreateContext();
            await SeedOfferAsync(db, "P1", "L1", 10m);
            await SeedOfferAsync(db, "P2", "L1", 20m);
