using Microsoft.EntityFrameworkCore;
using seed_b_backend.Api.Data;
using seed_b_backend.Api.Data.Entities;
using seed_b_backend.Api.Dtos;

namespace seed_b_backend.Api.Services;

public class OrderService(AppDbContext db)
{
    public async Task<CreateOrderResult> CreateOrderAsync(CreateOrderRequestDto request)
    {
        if (request.Items is not { Count: > 0 })
        {
            return CreateOrderResult.Rejected("empty-cart", "Der Warenkorb ist leer.");
        }

        if (request.Items.Any(i => i is null || i.Quantity < 1))
        {
            return CreateOrderResult.Rejected("invalid-quantity", "Der Warenkorb enthält eine ungültige Menge.");
        }

        var productIds = request.Items.Select(i => i.ProductId).Distinct().ToList();
        var offers = await db.Offers
            .Include(o => o.Product)
            .Include(o => o.Supplier)
            .Where(o => productIds.Contains(o.ProductId))
            .ToListAsync();
        var offersByKey = offers.ToDictionary(o => (o.ProductId, o.SupplierId));

        var orderItems = new List<OrderItem>();
        foreach (var item in request.Items)
        {
            if (!offersByKey.TryGetValue((item.ProductId, item.SupplierId), out var offer))
            {
                return CreateOrderResult.Rejected("offer-unavailable", "Ein Angebot im Warenkorb ist nicht mehr verfügbar.");
            }

            orderItems.Add(new OrderItem
            {
                Id = Guid.NewGuid(),
                ProductId = offer.ProductId,
                SupplierId = offer.SupplierId,
                ProductName = offer.Product!.Name,
                SupplierName = offer.Supplier!.Name,
                UnitPrice = offer.Price,
                Quantity = item.Quantity
            });
        }

        var order = new Order
        {
            Id = Guid.NewGuid(),
            Name = request.Name,
            Street = request.Street,
            PostalCode = request.PostalCode,
            City = request.City,
            Country = request.Country,
            Email = request.Email,
            Status = "Eingegangen",
            Items = orderItems
        };

        db.Orders.Add(order);
        await db.SaveChangesAsync();

        return CreateOrderResult.Success(order.Id);
    }
}

using Microsoft.EntityFrameworkCore;
using seed_b_backend.Api.Data;
using seed_b_backend.Api.Dtos;

namespace seed_b_backend.Api.Services;

public class ProductService(AppDbContext db)
{
    public async Task<ProductDetailDto?> GetProductDetailAsync(string id)
    {
        var rowsAffected = await db.Products
            .Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.ViewCount, p => p.ViewCount + 1));

        if (rowsAffected == 0)
        {
            return null; // Produkt existiert nicht -> Controller mappt auf 404, kein Increment fand statt
        }

        var product = await db.Products
            .Include(p => p.Subcategory!)
                .ThenInclude(s => s!.Category)
            .Include(p => p.Offers)
                .ThenInclude(o => o.Supplier)
            .FirstOrDefaultAsync(p => p.Id == id);

        if (product is null)
        {
            return null;
        }

        var attributes = (product.Subcategory?.AttributeNames ?? [])
            .Select(name => new { name, value = ProductAttributeJson.TryFormatValue(product.Attributes, name) })
            .Where(a => a.value is not null)
            .Select(a => new ProductAttributeDto(a.name, a.value!))
            .ToList();

        var ratingValues = await db.Ratings
            .Where(r => r.ProductId == id)
            .Select(r => r.Value)
            .ToListAsync();

        double? averageRating = ratingValues.Count == 0
            ? null
            : Math.Round(ratingValues.Average(), 1, MidpointRounding.AwayFromZero);

        var offers = product.Offers
            .OrderBy(o => o.Price)
            .ThenBy(o => o.SupplierId)
            .Select(o => new ProductOfferDto(o.SupplierId, o.Supplier!.Name, o.Price))
            .ToList();

        return new ProductDetailDto(
            product.Id,
            product.Name,
            product.Description,
            product.Subcategory!.CategoryId,
            product.Subcategory.Category!.Name,
            product.SubcategoryId,
            product.Subcategory.Name,
            attributes,
            averageRating,
            ratingValues.Count,
            offers);
    }
}

